def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full-length uniform divider lines.
    bg = max(range(10), key=lambda v: sum(row.count(v) for row in grid))
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    row_bounds = [-1] + div_rows + [h]
    col_bounds = [-1] + div_cols + [w]
    regions = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            regions.append((r0, r1, c0, c1))

    # The panel containing the most non-background cells provides the pattern.
    src = max(regions, key=lambda p: sum(
        grid[r][c] != bg
        for r in range(p[0], p[1]) for c in range(p[2], p[3])
    ))
    sr0, sr1, sc0, sc1 = src
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in regions:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = pattern[r - r0][c - c0]
    return out
